INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(51211, 'Jeremiah 19:1', 'Jeremiah', 19, 1, 'مالِک خُدائ ما ته وفرمائيل چې، ”لاړ شه او د کُلال نه يو د خټو منګے په بيعه واخله. او ځان سره د خلقو يو څو مشران او لوئ اِمامان بوځه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_1.mp3', '', 1761754199, 1761754199),
(51212, 'Jeremiah 19:2', 'Jeremiah', 19, 2, 'او د بنى‌هنوم وادۍ ته لاړ شه، او د کُلالانو د ماتو لوښو دروازې ته مخامخ هلته هغه پېغام خلقو ته بيان کړه کوم چې زۀ تا له درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_2.mp3', '', 1761754199, 1761754199),
(51213, 'Jeremiah 19:3', 'Jeremiah', 19, 3, 'مالِک خُدائ ما ته وفرمائيل چې هغوئ ته داسې ووايه، اے د يهوداه بادشاهانو او د يروشلم خلقو، مالِک خُدائ، ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى چې زۀ به په دې ځائ دومره سخت افت راولم، او چې څوک يې هم واورى نو د هغۀ غوږونه به وبوګنيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_3.mp3', '', 1761754199, 1761754199),
(51214, 'Jeremiah 19:4', 'Jeremiah', 19, 4, 'ځکه چې زۀ هغوئ پرېښے يم او دا ځائ يې غېرو معبودانو ته حواله کړو، او په دې ځائ کښې هغوئ هغه معبودانو ته داسې قربانۍ پېش کړې چې هغه نۀ دوئ په خپله او نۀ د دوئ پلار نيکۀ او نۀ د يهوداه بادشاهانو پخوا کړى وى. هغوئ دا زمکه د بې‌ګناه خلقو په وينو تويولو سره ډکه او رنګ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_4.mp3', '', 1761754199, 1761754199),
(51215, 'Jeremiah 19:5', 'Jeremiah', 19, 5, 'او هغوئ د بعل بُت دپاره علاقائى عبادتخانې جوړې کړې دى چې خپل بچى هلته په کښې د سوزېدونکى قربانۍ په توګه بعل بُت ته پېش کړى. د داسې کار ما نۀ هغوئ ته حکم ورکړے دے او نۀ مې په خيال خاطر کښې راغلى دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_5.mp3', '', 1761754199, 1761754199),
(51216, 'Jeremiah 19:6', 'Jeremiah', 19, 6, 'نو مالِک خُدائ فرمائى چې خبردار، هغه وخت راروان دے چې خلق به نور دې ځائ ته د ”توفت“ يا بنى‌هنوم وادى ونۀ وائى، بلکې دا به ”د قتل و غارت د وادۍ“ په نوم مشهوره شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_6.mp3', '', 1761754199, 1761754199),
(51217, 'Jeremiah 19:7', 'Jeremiah', 19, 7, 'په دې ځائ کښې به زۀ د يهوداه او د يروشلم د خلقو ټولې منصوبې تباه کړم. زۀ به هغوئ د هغه دشمن په لاس ووژنم، څوک چې د دوئ وينو ته تږى ناست دى، او زۀ به د دوئ لاشونه د هوا د مارغانو او د ځنګلى ځناورو خوراک کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_7.mp3', '', 1761754199, 1761754199),
(51218, 'Jeremiah 19:8', 'Jeremiah', 19, 8, 'زۀ به يروشلم تباه کړم، او د خلقو د خندا به يې کړم. څوک هم چې په دې لار تېريږى نو د هغوئ په تباهۍ به حق حېران شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_8.mp3', '', 1761754199, 1761754199),
(51219, 'Jeremiah 19:9', 'Jeremiah', 19, 9, 'زۀ به د هغوئ دشمنان څوک چې د هغوئ د وينو تږى دى راپاڅوم چې د دوئ ښار نه ګېره واچوى او دوئ ته غټ تکليف ورسوى. او دا ګېره به دومره سخته وى چې دوئ به د خپلو ماشومانو او ګاونډيانو په خوړلو شروع وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_9.mp3', '', 1761754199, 1761754199),
(51220, 'Jeremiah 19:10', 'Jeremiah', 19, 10, 'بيا مالِک خُدائ ما ته وفرمائيل چې هغه کسان چې تا خپل ځان سره بوتلى دى د هغوئ په وړاندې دا منګے چې تا سره دے مات کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_10.mp3', '', 1761754199, 1761754199),
(51221, 'Jeremiah 19:11', 'Jeremiah', 19, 11, 'او هغوئ ته ووايه چې مالِک خُدائ ربُ الافواج فرمائيلى دى، زۀ به د دې منګى په شان دا قوم او دا ښار ټوټې ټوټې کړم چې د بيا جوړېدو امکان به يې نۀ وى. په هغه وخت کښې به هغوئ خپل مړى په توفت کښې ښخوى، تر هغې پورې چې د ښخولو نور ځائ پاتې نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_11.mp3', '', 1761754199, 1761754199),
(51222, 'Jeremiah 19:12', 'Jeremiah', 19, 12, 'مالِک خُدائ فرمائى چې، زۀ به دې ښار او د دې د اوسېدونکو سره هم دغه رنګ وکړم. او د دوئ سره به د توفت په شان پليت سلوک وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_12.mp3', '', 1761754199, 1761754199),
(51223, 'Jeremiah 19:13', 'Jeremiah', 19, 13, 'زۀ به د يروشلم ټول کورونه، د يهوداه د بادشاهانو شاهى محلونه لکه د توفت په شان پليت وګرځوم، چا چې د خپلو کورونو په چتونو ستورو ته قربانۍ پېش کړې دى، او د څښلو نذرانې يې نورو بُتانو ته پېش کړې دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_13.mp3', '', 1761754199, 1761754199),
(51224, 'Jeremiah 19:14', 'Jeremiah', 19, 14, 'نو بيا يرمياه د توفت نه راواپس شو، کوم ځائ ته چې مالِک خُدائ هغه د پېغام ورکولو دپاره لېږلے وو. نو بيا هغه د مالِک خُدائ د کور په دربار کښې ودرېدو او ټولو خلقو ته يې وفرمائيل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_14.mp3', '', 1761754199, 1761754199),
(51225, 'Jeremiah 19:15', 'Jeremiah', 19, 15, '”مالِک خُدائ ربُ الافواج، د بنى اِسرائيلو خُدائ پاک فرمائى چې زۀ به په دې ښار او د دې نه ګېرچاپېره ښارونو هغه ټول افتونه راولم چې د کومو ما وړاندې ذکر کړے دے، ځکه چې تاسو په سرکشۍ سره زما خبرو اورېدلو ته تيار نۀ يئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah19_verse_15.mp3', '', 1761754199, 1761754199),
(51226, 'Psalms 104:1', 'Psalms', 104, 1, 'ووایه ثنا د څښتن ای زما ځانه! څومره عظیم یې ته زما څښتن خدایه! د لویۍ او د جلال لباس کې پټ یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_1.mp3', '', 1761754199, 1761754199),
(51227, 'Psalms 104:2', 'Psalms', 104, 2, 'تا په رڼا کې ځان پوښلی د کالیو په څېر تا اسمانونه غوړولي د خېمې په شان دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_2.mp3', '', 1761754199, 1761754199),
(51228, 'Psalms 104:3', 'Psalms', 104, 3, 'پاسنی چت دې د خپل کور جوړ کړی ورېځو باندې خپلې جنګي ګاډۍ په شان له ورېځو کار اخلې ته سپرېږې ته په وزرونو د باد', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_3.mp3', '', 1761754199, 1761754199),
(51229, 'Psalms 104:4', 'Psalms', 104, 4, 'ته د بادونو نه کار اخلې د استازو په شان د اور لمبې ته کاروې د خادمانو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_4.mp3', '', 1761754199, 1761754199),
(51230, 'Psalms 104:5', 'Psalms', 104, 5, 'تا درولې ځمکه داسې بنیادونو باندې هغه به هېڅکله ونه خوځیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_5.mp3', '', 1761754199, 1761754199),
(51231, 'Psalms 104:6', 'Psalms', 104, 6, 'په دریابونو باندې وپوښله ځمکه دې چپنې په څېر اوبو نیولي دي د غرو سرونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_6.mp3', '', 1761754199, 1761754199),
(51232, 'Psalms 104:7', 'Psalms', 104, 7, 'اوبه چې ورټلې تا نو هغه وتښتېدې ستا د تندر د اواز په اورېدو سره په منډه شولې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_7.mp3', '', 1761754199, 1761754199),
(51233, 'Psalms 104:8', 'Psalms', 104, 8, 'د غرو په څوکو باندې وبهېدې شولې درو ته ښکته لاړلې هغه ځای ته چې ټاکلی ورته تا ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_8.mp3', '', 1761754199, 1761754199),
(51234, 'Psalms 104:9', 'Psalms', 104, 9, 'تا ورته حد وټاکه چې ورنه تېرې نه شي څو یوځل بیا ځمکه ونه پوښي دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_9.mp3', '', 1761754199, 1761754199),
(51235, 'Psalms 104:10', 'Psalms', 104, 10, 'جاري کوې چینې درو کې ته ترڅو اوبه یې شي روانې د غونډیو منځ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_10.mp3', '', 1761754199, 1761754199),
(51236, 'Psalms 104:11', 'Psalms', 104, 11, 'د څښاک اوبه ورکوي ټولو ځنګلي ځناورو ته ماتوي تنده په دې د ځنګلي خرو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_11.mp3', '', 1761754199, 1761754199),
(51237, 'Psalms 104:12', 'Psalms', 104, 12, 'مرغان اوسیږي د اوبو په شاوخوا ونو کې وایي سندرې یې په څانګو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_12.mp3', '', 1761754199, 1761754199),
(51238, 'Psalms 104:13', 'Psalms', 104, 13, 'اوبه کوې غرونه له خپل اسماني کوره ستا د کارونو د ثمر ځینې بسیا ده ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_13.mp3', '', 1761754199, 1761754199),
(51239, 'Psalms 104:14', 'Psalms', 104, 14, 'راشنه کوې واښه څارویو لره د انسانانو په خاطر بوټي چې ویې کري ترڅو د ځمکې نه خواړه پیدا کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_14.mp3', '', 1761754199, 1761754199),
(51240, 'Psalms 104:15', 'Psalms', 104, 15, 'هم د انګورو شراب چې دوی یې خوښ کړي زیتونو تېل یې د مخونو د ځلا دپاره او هم خواړه چې دوی ته ورکړي قوت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_15.mp3', '', 1761754199, 1761754199),
(51241, 'Psalms 104:16', 'Psalms', 104, 16, 'د څښتن ونې ښې خړوبې شولې د سبر ونې د لبنان چې دي هغه کرلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_16.mp3', '', 1761754199, 1761754199),
(51242, 'Psalms 104:17', 'Psalms', 104, 17, 'جوړوي ځالې په هغو کې مرغان لري کورونه لګ‌لګان د صنوبر ونو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_17.mp3', '', 1761754199, 1761754199),
(51243, 'Psalms 104:18', 'Psalms', 104, 18, 'اوسیږي لوړو غرو کې ځنګلي وزې ګړنګونه پناه ځای د غرنۍ سویو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_18.mp3', '', 1761754199, 1761754199),
(51244, 'Psalms 104:19', 'Psalms', 104, 19, 'تا سپوږمۍ ده پیدا کړې چې معلومې کړو پرې میاشتې پوهیږي لمر چې پرېوځي څه وخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_19.mp3', '', 1761754199, 1761754199),
(51245, 'Psalms 104:20', 'Psalms', 104, 20, 'ته راولې تیاره او شپه جوړیږي ټول ځنګلي ځناور ګرځي په کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_20.mp3', '', 1761754199, 1761754199),
(51246, 'Psalms 104:21', 'Psalms', 104, 21, 'غړمبیږي ځوان زمریان ښکار پسې تیاروي چې ورته خدای هغه خواړه لټوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_21.mp3', '', 1761754199, 1761754199),
(51247, 'Psalms 104:22', 'Psalms', 104, 22, 'چې لمر راوخېژي، دوی بېرته ورځي خپلو غارو کې څملي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_22.mp3', '', 1761754199, 1761754199),
(51248, 'Psalms 104:23', 'Psalms', 104, 23, 'خپلو کارو پسې روان شي خلک او تر ماښامه پورې زیار وباسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_23.mp3', '', 1761754199, 1761754199),
(51249, 'Psalms 104:24', 'Psalms', 104, 24, 'تا دي جوړ کړي ای څښتنه ډول ډول شیان ټول دې جوړ کړي د حکمت له مخې په مخلوقاتو ځمکه ډکه ده ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_24.mp3', '', 1761754199, 1761754199),
(51250, 'Psalms 104:25', 'Psalms', 104, 25, 'دریابونه دي پراخه او لوی چې بې‌شمېره مخلوقات په کې اوسیږي که کوچني دي یا غټ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_25.mp3', '', 1761754199, 1761754199),
(51251, 'Psalms 104:26', 'Psalms', 104, 26, 'وګورئ کشتۍ چې دي روانې د هغوی په سر او نهنګ چې پیدا کړی دی تا او په کې لوبې کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_26.mp3', '', 1761754199, 1761754199),
(51252, 'Psalms 104:27', 'Psalms', 104, 27, 'هغه ټول دي په تمه تاته چې په خپل وخت ورته خواړه ورکړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_27.mp3', '', 1761754199, 1761754199),
(51253, 'Psalms 104:28', 'Psalms', 104, 28, 'ته چې هغوی ته ورکوې کوم شیان، راټولوي یې هغوی ستا د لاس په خلاصېدو، ماړه کیږي هغوی په ښو شیانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_28.mp3', '', 1761754199, 1761754199),
(51254, 'Psalms 104:29', 'Psalms', 104, 29, 'چې مخ ترې واړوې نو سخت وېریږي هغوی چې ساه ترې واخلې نو مړه کیږي هغوی او ورځي بېرته هغې خاورې ته چې جوړ شوي ورنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_29.mp3', '', 1761754199, 1761754199),
(51255, 'Psalms 104:30', 'Psalms', 104, 30, 'چې کله ورکړې ورته ساه نو ژوندي شي هغوی او ورکوې ځمکې ته نوی ژوندون', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_30.mp3', '', 1761754199, 1761754199),
(51256, 'Psalms 104:31', 'Psalms', 104, 31, 'وي تر ابده دې جلال د څښتن خپلو کارونو باندې وي دې خوشحاله څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_31.mp3', '', 1761754199, 1761754199),
(51257, 'Psalms 104:32', 'Psalms', 104, 32, 'چې ځمکې ته وګوري نو په لړزان شي هغه چې غرو ته لاس وروړي نو ترې راوځي لوګی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_32.mp3', '', 1761754199, 1761754199),
(51258, 'Psalms 104:33', 'Psalms', 104, 33, 'زه به خپل ټول عمر سندره د څښتن وایمه ترڅو ژوندی یم زه ثنا به د خپل خدای وایمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_33.mp3', '', 1761754199, 1761754199),
(51259, 'Psalms 104:34', 'Psalms', 104, 34, 'وي دې خوشحاله په خیالونو زما ځکه چې زه یمه خوشحاله د څښتنه څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_34.mp3', '', 1761754199, 1761754199),
(51260, 'Psalms 104:35', 'Psalms', 104, 35, 'شي نابود ګناهکاران دې ټول د ځمکې پاتې دې نه شي بدعمله نور ووایه ثنا ته د څښتن ای زما ځانه! د څښتن ثنا او صفت وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms104_verse_35.mp3', '', 1761754199, 1761754199),
(51261, 'Genesis 19:1', 'Genesis', 19, 1, 'کله چې هغه دوه فرښتې د ماښام په وخت کې سدوم ته ورسېدلې، لوط د ښار په دروازه کې ناست ؤ. څنګه چې لوط هغوی ولیدلې، راپاڅېده او د هغوی د هرکلي دپاره ورغی او د درناوي په خاطر یې ورته خپل سر ټیټ کړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_1.mp3', '', 1761754199, 1761754199),
(51262, 'Genesis 19:2', 'Genesis', 19, 2, 'او ویې ویل: «ای زما بادارانو، د خپل خدمتګار کور ته راشئ. تاسو کولای شئ خپلې پښې ووینځئ او دلته شپه تېره کړئ. سهار وختي پاڅېږئ او په خپله لاره روان شئ.» خو هغوی ورته په ځواب کې وویل: «نه، مونږ به د ښار په چوک کې شپه تېره کړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_2.mp3', '', 1761754199, 1761754199),
(51263, 'Genesis 19:3', 'Genesis', 19, 3, 'خو لوط په هغوی باندې ډېر سخت ټینګار وکړ، ترڅو هغوی ورسره د هغه کور ته لاړلې. هغه د هغوی دپاره خوراک تیار کړ او فطیره ډوډۍ یې ورته پخه کړه او هغوی وخوړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_3.mp3', '', 1761754199, 1761754199),
(51264, 'Genesis 19:4', 'Genesis', 19, 4, 'هغوی لا ویده شوي نه وو چې د سدوم د ښار خلک له هرې خوا د ځوان څخه نیولې تر زاړه پورې ټول د کور څخه راچاپېر شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_4.mp3', '', 1761754199, 1761754199),
(51265, 'Genesis 19:5', 'Genesis', 19, 5, 'هغوی لوط ته غږ وکړ: «هغه دوه کسان چې نن شپه ستا سره راغلي وو، چېرته دي؟ هغوی مونږ له راوباسه چې بد کار ورسره وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_5.mp3', '', 1761754199, 1761754199),
(51266, 'Genesis 19:6', 'Genesis', 19, 6, 'لوط دباندې ووت او دروازه یې د ځان پسې بنده کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_6.mp3', '', 1761754199, 1761754199),
(51267, 'Genesis 19:7', 'Genesis', 19, 7, 'او هغوی ته یې وویل: «ای ورونو! زه تاسو ته زاري کوم چې داسې بد کار مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_7.mp3', '', 1761754199, 1761754199),
(51268, 'Genesis 19:8', 'Genesis', 19, 8, 'ګورئ، زه دوه لورګانې لرم چې تر‌اوسه پورې لا پېغلې دي. هغوی به تاسو ته راوباسم، هرڅه چې غواړئ د هغوی سره یې وکړئ، خو د دې خلکو سره هېڅ مه کوئ، ځکه چې هغوی ماته پناه راوړې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_8.mp3', '', 1761754199, 1761754199),
(51269, 'Genesis 19:9', 'Genesis', 19, 9, 'هغوی ځواب ورکړ: «زمونږ د لارې څخه لېرې شه» او ویې ویل: «ای پردی سړیه! زمونږ له مخې څخه لېرې شه، ته څوک یې چې مونږ ته وایې چې څه باید وکړو؟ زمونږ د مخې څخه لېرې شه. که نه، نو ستا سره به تر هغوی بد عمل وکړو.» هغوی لوط بېرته ټېل واهه او نژدې شول چې دروازه ماته کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_9.mp3', '', 1761754199, 1761754199),
