(51271, 'Genesis 19:11', 'Genesis', 19, 11, 'نو بیا هغوی هغه ټول خلک چې دباندې ولاړ وو ړانده کړل، ترڅو هغوی ونه شي کولای چې دروازه پیدا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_11.mp3', '', 1761754199, 1761754199),
(51272, 'Genesis 19:12', 'Genesis', 19, 12, 'هغو دوه کسانو لوط ته وویل: «که دلته ستا نور څوک یعنې زامن، لورګانې، زومان او نور خپلوان په دې ښار کې اوسیږي، نو د دې ښار څخه یې وباسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_12.mp3', '', 1761754199, 1761754199),
(51273, 'Genesis 19:13', 'Genesis', 19, 13, 'ځکه چې مونږ غواړو دغه ځای وران کړو. د دې خلکو په ضد څښتن ډېر فریادونه اورېدلي دي او مونږ یې رالېږلي یو چې سدوم له منځه یوسو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_13.mp3', '', 1761754199, 1761754199),
(51274, 'Genesis 19:14', 'Genesis', 19, 14, 'نو لوط دباندې ووت، د خپلو زومانو سره یې چې د هغه د لورګانو سره یې کوژدنې شوې وې، خبرې وکړې او ویې ویل: «زر پاڅئ او د دې ځای څخه ووځئ. څښتن غواړي چې دا ځای له منځه یوسي.» خو د هغه زومانو فکر کاوه چې هغه ټوکې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_14.mp3', '', 1761754199, 1761754199),
(51275, 'Genesis 19:15', 'Genesis', 19, 15, 'سهار وختي فرښتو لوط وهڅاوه او ورته ویې ویل: «پاڅه! خپله ښځه او دواړه لورګانې دې واخله او ووځه، ترڅو د دې ښار په ورانېدلو سره تاسو خپل ژوند له لاسه ورنه کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_15.mp3', '', 1761754199, 1761754199),
(51276, 'Genesis 19:16', 'Genesis', 19, 16, 'هغه وخت لوط زړه نازړه کېده، خو بیاهم څښتن په هغه باندې مهربانه شو او هغو کسانو د ده او د ده د ښځې او لورګانو لاسونه ونیول او هغوی یې په امن سره د ښار څخه دباندې وویستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_16.mp3', '', 1761754199, 1761754199),
(51277, 'Genesis 19:17', 'Genesis', 19, 17, 'بیا یوې فرښتې ورته وویل: «د دې دپاره چې ژوندي پاتې شئ، نو وتښتئ! شاته مه ګورئ او په ټوله دره کې ونه درېږئ. غرونو ته وتښتئ چې ونه وژل شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_17.mp3', '', 1761754199, 1761754199),
(51278, 'Genesis 19:18', 'Genesis', 19, 18, 'خو لوط هغوی ته وویل: «نه، ای زما بادارانو په مونږ باندې داسې مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_18.mp3', '', 1761754199, 1761754199),
(51279, 'Genesis 19:19', 'Genesis', 19, 19, 'تاسو زما سره ډېر لوی احسان کړی دی او زما ژوند مو ژغورلی دی، خو زه نه شم کولای چې غرونو ته وتښتم. نو مخکې له دې چې هغه ځای ته ورسېږم، دا بدبختي به په ما باندې راشي او زه به مړ شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_19.mp3', '', 1761754199, 1761754199),
(51280, 'Genesis 19:20', 'Genesis', 19, 20, 'ایا تاسو هغه وړوکی ښار وینئ؟ هغه ډېر نژدې دی، اجازه راکړئ چې هلته لاړ شم. تاسو ګورئ چې هغه یو وړوکی ځای دی. زه به هلته په امن کې یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_20.mp3', '', 1761754199, 1761754199),
(51281, 'Genesis 19:21', 'Genesis', 19, 21, 'هغه ځواب ورکړ: «ډېر ښه، زه به ستا دغه غوښتنه هم پوره کړم. زه به دغه ښار وران نه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_21.mp3', '', 1761754199, 1761754199),
