(51283, 'Genesis 19:23', 'Genesis', 19, 23, 'کله چې لوط صوغر ته ورسېده، لمر راوخوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_23.mp3', '', 1761754199, 1761754199),
(51284, 'Genesis 19:24', 'Genesis', 19, 24, 'په هغه وخت کې څښتن د اسمان څخه په سدوم او عموره باندې سوځوونکي ګوګړ وورول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_24.mp3', '', 1761754199, 1761754199),
