(51296, 'Genesis 19:36', 'Genesis', 19, 36, 'په دې ډول د لوط دواړه لورګانې د خپل پلار په وسیله امیدوارې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_36.mp3', '', 1761754199, 1761754199),
(51297, 'Genesis 19:37', 'Genesis', 19, 37, 'د مشرې لور زوی پیدا شو او په هغه باندې یې موآب نوم کېښود او هغه د اوسنیو موآبیانو پلار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis19_verse_37.mp3', '', 1761754199, 1761754199),
