(51301, 'Ezekiel 42:3', 'Ezekiel', 42, 3, 'د ودانۍ یوې خواته یوه ساحه وه چې د عبادتځای په خوا کې وه او لس متره سور یې درلود. بله خوا یې د باندینۍ حوېلۍ لارې ته مخامخ وه. ودانۍ په درېو منزلو کې جوړه شوې وه او هر منزل د لاندېني منزل په پرتله شاته ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_3.mp3', '', 1761754199, 1761754199),
(51302, 'Ezekiel 42:4', 'Ezekiel', 42, 4, 'د دنننۍ حوېلۍ خواته او د ودانۍ د کوټو په مخکې یوه لاره وه چې سور یې پنځه متره ؤ. د ودانۍ شمال خواته هم یوه لاره وه چې نیم متر پراخه وه او دروازې یې هم شمال خواته خلاصېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_4.mp3', '', 1761754199, 1761754199),
(51303, 'Ezekiel 42:5', 'Ezekiel', 42, 5, 'نو د ودانۍ پاسنۍ کوټې د منځنیو او لاندېنیو کوټو نه تنګې وې، ځکه چې هغه شاته جوړې شوې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_5.mp3', '', 1761754199, 1761754199),
(51304, 'Ezekiel 42:6', 'Ezekiel', 42, 6, 'کوټې په درېو منزلو کې جوړې شوې وې، خو د حوېلیو د ودانیو په شان یې ستنې نه درلودلې. له دې امله پاسنۍ کوټې د لاندېنیو او منځنیو کوټو په پرتله شاته جوړې شوې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_6.mp3', '', 1761754199, 1761754199),
(51305, 'Ezekiel 42:7', 'Ezekiel', 42, 7, 'په باندینۍ حوېلۍ کې دې ودانۍ ته موازي یو دېوال ؤ او دا د ودانۍ د دېوال نیمایې برخه وه چې اوږدوالی یې پنځه ویشت متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_7.mp3', '', 1761754199, 1761754199),
(51306, 'Ezekiel 42:8', 'Ezekiel', 42, 8, 'دا دېوال ځکه داسې ؤ چې د باندینۍ حوېلۍ د ودانۍ اوږدوالی پنځه ویشت متره ؤ، سره له دې چې د عبادتځای مخامخ ودانۍ پنځوس متره پراخه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_8.mp3', '', 1761754199, 1761754199),
(51307, 'Ezekiel 42:11', 'Ezekiel', 42, 11, 'د دې کوټو په مخ کې یوه لاره وه او دا کوټې د شمال د کوټو په شان وې. د ودانۍ مساحت، نقشې او د وتلو دروازې هم د شمال د کوټو په شان وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_11.mp3', '', 1761754199, 1761754199),
(51308, 'Ezekiel 42:12', 'Ezekiel', 42, 12, 'د جنوبي ودانۍ دروازې جنوب خواته خلاصېدلې. ودانۍ ته مخامخ د شمال په شان یو دېوال ؤ چې یوه لاره یې درلودله. د دې لارې په پیل کې داسې یوه دروازه وه چې دې ودانۍ ته د ورننوتلو لاره وه او ختیځ خواته خلاصېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_12.mp3', '', 1761754199, 1761754199),
(51309, 'Ezekiel 42:13', 'Ezekiel', 42, 13, 'هغه سړي بیا ماته وویل: «د شمال او جنوب خواته، د عبادتځای شاته د خالي ځای په مخکې، دا دواړه ودانۍ سپېڅلې دي. په هغو کې هغه کاهنان چې د څښتن حضور ته ورځي، ډېرې سپېڅلې نذرانې خوري. هغوی هلته هغه نذرانې ځای په ځای کوي، لکه د غلو دانو نذرانې، د ګناه دپاره نذرانې او د تاوان دپاره نذرانې، ځکه چې هغه کوټې سپېڅلې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_13.mp3', '', 1761754199, 1761754199),
(51310, 'Ezekiel 42:14', 'Ezekiel', 42, 14, 'کله چې کاهنان د عبادت په ځای کې وي او وغواړي چې باندینۍ حوېلۍ ته لاړ شي، نو هغوی چې د څښتن د خدمت کولو دپاره کوم کالي اغوستي وو، هغه دې په دې کوټو کې پرېږدي، ځکه چې دا کالي سپېڅلي دي. مخکې له دې چې هغوی هغه ځای ته لاړ شي چې نور خلک په کې راټولیږي، نو باید نور کالي واغوندي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_14.mp3', '', 1761754199, 1761754199);